import javax.swing.*;import java.awt.*;import java.sql.*;
public class AdminWindow extends JFrame {
    String adminId;public AdminWindow(String id){adminId=id;setTitle("Administrator Dashboard");setSize(600,440);setLocationRelativeTo(null);JPanel p=UI.panel();p.setLayout(new BoxLayout(p,BoxLayout.Y_AXIS));JLabel h=new JLabel("ADMINISTRATOR DASHBOARD");h.setForeground(Color.WHITE);h.setFont(new Font("SansSerif",Font.BOLD,22));h.setAlignmentX(CENTER_ALIGNMENT);p.add(h);String status="Election status: ";try{status+=UI.electionStatus();}catch(Exception e){status+="unknown";}JLabel st=new JLabel(status);st.setForeground(Color.WHITE);st.setAlignmentX(CENTER_ALIGNMENT);p.add(st);
        JButton start=UI.button("START ELECTION"),stop=UI.button("STOP ELECTION"),results=UI.button("VIEW RESULTS"),voters=UI.button("VIEW VOTERS LIST"),reset=UI.button("RESET ELECTIONS"),logout=UI.button("LOG OUT");for(JButton b:new JButton[]{start,stop,results,voters,reset,logout}){b.setAlignmentX(CENTER_ALIGNMENT);p.add(b);p.add(Box.createVerticalStrut(8));}start.addActionListener(e->setStatus("active"));stop.addActionListener(e->setStatus("inactive"));results.addActionListener(e->ResultWindow.showResults(this));voters.addActionListener(e->showVoters());reset.addActionListener(e->reset());logout.addActionListener(e->{new Login().setVisible(true);dispose();});add(p);}
    private void setStatus(String value){try(Connection c=DbConfig.connect();PreparedStatement s=c.prepareStatement("UPDATE Elections SET status=? WHERE id=1")){s.setString(1,value);s.executeUpdate();UI.msg(this,"Election is now "+value+".");dispose();new AdminWindow(adminId).setVisible(true);}catch(Exception e){UI.error(this,e);}}
    private void showVoters(){try(Connection c=DbConfig.connect();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT student_id,student_name,student_email FROM Students WHERE has_voted=TRUE ORDER BY student_id")){StringBuilder b=new StringBuilder("VOTERS WHO HAVE VOTED\n\n");while(r.next())b.append(r.getString(1)).append(" | ").append(r.getString(2)).append(" | ").append(r.getString(3)).append("\n");JTextArea a=new JTextArea(b.toString());a.setEditable(false);JOptionPane.showMessageDialog(this,new JScrollPane(a),"Voters List",JOptionPane.INFORMATION_MESSAGE);}catch(Exception e){UI.error(this,e);}}
    private void reset(){String pw=JOptionPane.showInputDialog(this,"Re-enter administrator password:");if(pw==null)return;try(Connection c=DbConfig.connect();PreparedStatement s=c.prepareStatement("SELECT admin_id FROM Admin WHERE admin_id=? AND password=?")){s.setString(1,adminId);s.setString(2,pw);try(ResultSet r=s.executeQuery()){if(!r.next()){UI.msg(this,"Incorrect password.");return;}}int ok=JOptionPane.showConfirmDialog(this,"Delete candidates and clear all voted status?","Confirm reset",JOptionPane.YES_NO_OPTION);if(ok!=JOptionPane.YES_OPTION)return;try(Connection x=DbConfig.connect()){x.setAutoCommit(false);try(Statement q=x.createStatement()){q.executeUpdate("DELETE FROM Candidates");q.executeUpdate("UPDATE Students SET has_voted=FALSE");q.executeUpdate("UPDATE Elections SET status='inactive' WHERE id=1");}x.commit();}UI.msg(this,"Election reset successfully.");dispose();new AdminWindow(adminId).setVisible(true);}catch(Exception e){UI.error(this,e);}}
}
